class Solution:
    def longestPalindrome(self, s: str) -> str:
        best = ""

        def is_pal(l: int, r: int) -> bool:
            if l >= r:
                return True
            return s[l] == s[r] and is_pal(l + 1, r - 1)

        def scan(l: int, r: int) -> None:
            nonlocal best
            if l == len(s):
                return
            if r == len(s):
                scan(l + 1, l + 1)
                return
            if r - l + 1 > len(best) and is_pal(l, r):
                best = s[l:r + 1]
            scan(l, r + 1)

        scan(0, 0)
        return best

