class Solution:
    def longestPalindrome(self, s: str) -> str:
        memo = {}

        def is_pal(l: int, r: int) -> bool:
            if l >= r:
                return True
            if (l, r) not in memo:
                memo[(l, r)] = s[l] == s[r] and is_pal(l + 1, r - 1)
            return memo[(l, r)]

        best = s[0]
        for l in range(len(s)):
            for r in range(l, len(s)):
                if r - l + 1 > len(best) and is_pal(l, r):
                    best = s[l:r + 1]
        return best

