class Solution:
    def longestPalindrome(self, s: str) -> str:
        n = len(s)
        dp = [False] * n
        start, best_len = 0, 1

        for l in range(n - 1, -1, -1):
            new_dp = [False] * n
            for r in range(l, n):
                new_dp[r] = s[l] == s[r] and (r - l < 2 or dp[r - 1])
                if new_dp[r] and r - l + 1 > best_len:
                    start, best_len = l, r - l + 1
            dp = new_dp

        return s[start:start + best_len]

